use crate::{studio_files as disk,image_index_fs};
use std::{fs,path::Path,io::Read};
use serde_json::{Value,json};
fn read(path:&Path)->Result<Value,String>{let m=fs::metadata(path).map_err(|e|e.to_string())?;if m.len()>16*1024*1024{return Err("A Studio Link file exceeds 16 MB".into())}serde_json::from_slice(&fs::read(path).map_err(|e|e.to_string())?).map_err(|e|format!("Unreadable Studio Link file: {e}"))}
fn owner(root:&Path,id:&str)->Result<(),String>{if id.is_empty()||id.len()>200{return Err("Invalid project identity".into())}let path=root.join("Studio Link/project.json");if path.exists(){let p=read(&path)?;if p["format"]!="studio-link-project-v1"||p["project"]["id"].as_str()!=Some(id){return Err("This Studio Link folder belongs to another project. Choose its matching project or another folder.".into())}}Ok(())}
#[tauri::command]
pub async fn sync_studio_link(directory:String,project_id:String,manifest:String,reference:String,script:String)->Result<String,String>{tauri::async_runtime::spawn_blocking(move||{
 let root=disk::root(&directory)?;let _workflow=crate::media_organization::lock(&root)?;owner(&root,&project_id)?;
 let m:Value=serde_json::from_str(&manifest).map_err(|e|e.to_string())?;let r:Value=serde_json::from_str(&reference).map_err(|e|e.to_string())?;let s:Value=serde_json::from_str(&script).map_err(|e|e.to_string())?;
 if m["format"]!="studio-link-project-v1"||m["project"]["id"].as_str()!=Some(project_id.as_str())||r["project"]["id"].as_str()!=Some(project_id.as_str())||s["studioProjectId"].as_str()!=Some(project_id.as_str()){return Err("Invalid Studio Link project data".into())}
 let previous=root.join("Studio Link/project.json");if previous.exists(){let old=read(&previous)?;if old["namingRevision"].is_string()&&old["namingRevision"]!=m["namingRevision"]{return Err("Project folder names changed. Refresh the project before saving shared records.".into())}}if !previous.exists()||read(&previous).ok().map(|v|v["maintenanceVersion"]!=1).unwrap_or(false){let _=crate::owned_output::retire_timeline_maps(&root,&project_id);}
 let link=disk::subdir(&root,"Studio Link")?;
 for item in m["chapterDirectories"].as_array().ok_or("Invalid chapter directories")?{disk::relative(item["path"].as_str().ok_or("Missing chapter path")?)?;}
 // Create chapter folders only when an image is actually written. Retire empty legacy folders.
 if let Some(paths)=m["cleanupChapterDirectories"].as_array(){for value in paths{if let Some(value)=value.as_str(){if let Ok(rel)=disk::relative(value){let path=root.join(rel);if path.is_dir()&&!fs::symlink_metadata(&path).map(|m|m.file_type().is_symlink()).unwrap_or(true){if path.canonicalize().map(|p|p.starts_with(&root)).unwrap_or(false){let _=fs::remove_dir(path);}}}}}}
 refresh_inventory_labels(&link,&r)?;
 // Timing text/intervals and export ownership remain with their producing app.
 for(name,data)in[("storyboard.ssreference.json",reference),("spoken-script.json",script),("project.json",manifest)]{if data.len()>16*1024*1024{return Err("Studio Link data exceeds 16 MB".into())}disk::atomic_json(&link,name,&data)?;}
 Ok(root.to_string_lossy().into_owned())
}).await.map_err(|e|e.to_string())?}
#[tauri::command]
pub async fn inspect_studio_link(directory:String,project_id:String)->Result<Value,String>{tauri::async_runtime::spawn_blocking(move||{
 let root=disk::root(&directory)?;owner(&root,&project_id)?;let link=root.join("Studio Link");if !link.is_dir(){return Err("Studio Link is missing. Select the project folder to reconnect it.".into())}
 let link=link.canonicalize().map_err(|e|e.to_string())?;if !link.starts_with(&root){return Err("Studio Link points outside this project".into())}let manifest=read(&link.join("project.json"))?;let mut handoffs=Vec::new();let mut warnings=Vec::new();
 for base_dir in [&link,&root]{for entry in fs::read_dir(base_dir).map_err(|e|e.to_string())?.take(256){let path=entry.map_err(|e|e.to_string())?.path();if path.extension().and_then(|s|s.to_str())!=Some("json")||!path.is_file(){continue;}match read(&path){Ok(v)=>{let f=v["format"].as_str().unwrap_or("");if f=="folderexporter-index-v1"||f=="whisperdesk-timing-v1"||f=="subtitler-timing-v1"{let base=if let Some(relative)=v["mediaRoot"].as_str(){if relative=="."{root.clone()}else{{let p=root.join(disk::relative(relative)?).canonicalize().map_err(|e|e.to_string())?;if !p.starts_with(&root)||!p.is_dir(){return Err("Invalid media root".into())}p}}}else{base_dir.to_path_buf()};handoffs.push(json!({"filename":path.file_name().unwrap_or_default().to_string_lossy(),"directory":base.to_string_lossy(),"text":v.to_string()}));}},Err(e)=>warnings.push(e)} }}
 let mut media=Vec::new();fn scan(root:&Path,dir:&Path,depth:u8,out:&mut Vec<Value>)->Result<(),String>{if depth>0||out.len()>=4096{return Ok(())}for e in fs::read_dir(dir).map_err(|e|e.to_string())?{let e=e.map_err(|e|e.to_string())?;let kind=e.file_type().map_err(|e|e.to_string())?;if kind.is_symlink(){continue;}let p=e.path();if kind.is_dir(){if e.file_name()!="Studio Link"{scan(root,&p,depth+1,out)?;}}else if kind.is_file()&&["wav","mp3","m4a","aac","flac","ogg","opus","aiff","aif","wma"].contains(&p.extension().and_then(|s|s.to_str()).unwrap_or("").to_lowercase().as_str()){let(size,modified)=disk::metadata(&p)?;out.push(json!({"name":e.file_name().to_string_lossy(),"path":p.to_string_lossy(),"relativePath":p.strip_prefix(root).unwrap().to_string_lossy().replace('\\',"/"),"size":size,"modified":modified}));if out.len()>=4096{break}}}Ok(())}scan(&root,&root,0,&mut media)?;
 let mut chapter_folders=Vec::new();if let Some(chapters)=manifest["chapterDirectories"].as_array(){for ch in chapters{if let Some(path)=ch["path"].as_str(){if let Ok(rel)=disk::relative(path){let folder=root.join(rel);let state=if !folder.exists(){"missing"}else if folder.is_dir()&&fs::read_dir(&folder).map(|mut i|i.next().is_none()).unwrap_or(false){"empty"}else{"used"};chapter_folders.push(json!({"path":path,"state":state}));}}}}
 Ok(json!({"chapterFolders":chapter_folders,"directory":root.to_string_lossy(),"manifest":manifest,"handoffs":handoffs,"audioFiles":media,"warnings":warnings}))
}).await.map_err(|e|e.to_string())?}
#[tauri::command]
pub fn write_project_output(directory:String,relative_path:String,base64_data:String,project_id:String,owner_key:String)->Result<Value,String>{let root=disk::root(&directory)?;if base64_data.len()>180*1024*1024{return Err("Output exceeds 128 MB".into())}use base64::Engine;let bytes=base64::engine::general_purpose::STANDARD.decode(base64_data).map_err(|e|e.to_string())?;owner(&root,&project_id)?;let path=crate::owned_output::write(&root,&relative_path,&bytes,&project_id,&owner_key)?;let full=root.join(&path);let(size,modified)=disk::metadata(&full)?;Ok(json!({"path":full.to_string_lossy(),"relativePath":path,"size":size,"modified":modified,"fingerprint":crate::owned_output::fingerprint(&bytes)}))}
#[tauri::command]
pub fn inspect_linked_audio(path:String)->Result<Value,String>{let p=Path::new(&path);if !p.is_absolute()||!["wav","mp3","m4a","aac","flac","ogg","opus","aiff","aif","wma"].contains(&p.extension().and_then(|s|s.to_str()).unwrap_or("").to_lowercase().as_str()){return Err("Choose an audio file".into())}let p=p.canonicalize().map_err(|_|"Audio is missing. Relink its original file.".to_string())?;let(size,modified)=disk::metadata(&p)?;let mut bytes=Vec::new();fs::File::open(&p).map_err(|e|e.to_string())?.take(65536).read_to_end(&mut bytes).map_err(|e|e.to_string())?;use base64::Engine;Ok(json!({"path":p.to_string_lossy(),"name":p.file_name().unwrap_or_default().to_string_lossy(),"size":size,"modified":modified,"fingerprint":crate::audio_identity::info(&p)?["fingerprint"],"header":base64::engine::general_purpose::STANDARD.encode(bytes)}))}
#[tauri::command]
pub fn pick_timing_audio()->Option<String>{rfd::FileDialog::new().set_title("Locate original recording").add_filter("Audio",&["wav","mp3","m4a","aac","flac","ogg","opus","aiff","aif","wma"]).pick_file().map(|p|p.to_string_lossy().into_owned())}
#[tauri::command]
pub fn reserve_project_timeline(directory:String,filename:String,project_id:String)->Result<Value,String>{let root=disk::root(&directory)?;owner(&root,&project_id)?;if !(filename.ends_with(".xml")||filename.ends_with(".fcpxml"))||filename.contains('/')||filename.contains('\\'){return Err("Invalid timeline name".into())}crate::owned_output::check(&root,&filename,&project_id,&format!("timeline:{filename}"))?;let name=filename;Ok(json!({"filename":name,"directory":root.to_string_lossy()}))}
#[tauri::command]
pub fn write_linked_timeline(directory:String,project_id:String,filename:String,xml:String,images:Vec<Value>,audios:Vec<String>)->Result<String,String>{let root=disk::root(&directory)?;owner(&root,&project_id)?;if filename.contains('/')||filename.contains('\\')||!(filename.ends_with(".xml")||filename.ends_with(".fcpxml"))||xml.len()>32*1024*1024{return Err("Invalid timeline output".into())}
 for im in images{let dir=im["root"].as_str().ok_or("Missing image folder")?;let image_root=Path::new(dir).canonicalize().map_err(|e|e.to_string())?;let p=image_index_fs::resolve_image(&image_root,im["relativePath"].as_str().ok_or("Missing image path")?)?;let(size,modified)=disk::metadata(&p)?;if im["size"].as_u64()!=Some(size)||im["modified"].as_u64()!=Some(modified){return Err("An image changed after it was checked. Export again to recheck it.".into())}}
 for path in audios{let p=Path::new(&path);if !p.is_absolute()||!p.is_file(){return Err("Audio is missing. Relink it before exporting.".into())}}
 crate::owned_output::write(&root,&filename,xml.as_bytes(),&project_id,&format!("timeline:{filename}"))?;Ok(root.join(filename).to_string_lossy().into_owned())}

// Refresh only descriptive numbers/paths in inventories. Their export dates,
// source structure and drawing variant snapshots retain their original meaning.
fn refresh_inventory_labels(link:&Path,reference:&Value)->Result<(),String>{
 let mut cards=std::collections::HashMap::new();if let Some(chapters)=reference["chapters"].as_array(){for ch in chapters{if let Some(list)=ch["cards"].as_array(){for c in list{if let Some(id)=c["id"].as_str(){cards.insert(id.to_string(),(ch,c));}}}}}
 for ent in fs::read_dir(link).map_err(|e|e.to_string())?{let ent=ent.map_err(|e|e.to_string())?;let name=ent.file_name().to_string_lossy().to_string();if !name.starts_with("folderexporter-index")||!name.ends_with(".json")||!ent.file_type().map_err(|e|e.to_string())?.is_file(){continue}let mut data=read(&ent.path())?;let pid=data["studioProjectId"].as_str().or_else(||data["storyboardReference"]["project"]["id"].as_str());if pid!=reference["project"]["id"].as_str(){continue}let old=data.clone();if let Some(frames)=data["frames"].as_array_mut(){for frame in frames{if let Some((ch,c))=frame["cardId"].as_str().and_then(|id|cards.get(id)){frame["cardNumber"]=c["number"].clone();frame["globalCardNumber"]=c["globalNumber"].clone();frame["displayCardNumber"]=c["displayNumber"].clone();frame["frameLabel"]=c["frameLabel"].clone();frame["chapterId"]=ch["id"].clone();frame["chapterNumber"]=ch["number"].clone();frame["chapterTitle"]=ch["title"].clone();}if let Some(refs)=frame["cardReferences"].as_array_mut(){for appearance in refs{if let Some((ch,c))=appearance["cardId"].as_str().and_then(|id|cards.get(id)){appearance["cardNumber"]=c["number"].clone();appearance["globalCardNumber"]=c["globalNumber"].clone();appearance["displayCardNumber"]=c["displayNumber"].clone();appearance["chapterId"]=ch["id"].clone();appearance["chapterNumber"]=ch["number"].clone();appearance["chapterTitle"]=ch["title"].clone();}}}}}if data!=old{data["pathRevision"]=json!(format!("labels-{}",std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_nanos()));disk::atomic_json(link,&name,&data.to_string())?;}}
 Ok(())
}

#[tauri::command]pub fn pick_project_audio()->Option<String>{rfd::FileDialog::new().set_title("Choose project recording").add_filter("Audio",&["wav","mp3","m4a","aac","flac","ogg","opus","aif","aiff","wma"]).pick_file().map(|p|p.to_string_lossy().into_owned())}
